// =====================================================================
// NassakhRTL - RTL text fixer for Affinity apps
// Engine + UI in conservative C# 5 (compiles under Windows PowerShell 5.1)
// Source is pure ASCII; all Unicode via \u escapes.
// =====================================================================
namespace RTLFixer {

using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows.Forms;
using System.Runtime.InteropServices;

// ------------------------------------------------------------------ //
//  Conversion options + result
// ------------------------------------------------------------------ //
public class FixOptions {
    public bool WesternDigits = true;
    public bool RemoveZeroWidth = true;
    public bool RemoveDiacritics = false;
    public bool RemoveTatweel = false;
    public bool PunctToLatin = false;
    public bool NormalizeAlef = false;
    public bool NormalizeYaTa = false;
    // 0 = off. When > 0, long logical lines are hard-broken at word
    // boundaries BEFORE conversion. Without this, a wrapping paragraph
    // pasted into Affinity re-wraps the reversed string and the line
    // order comes out bottom-to-top.
    public int WrapWidth = 0;

    // Serialize to/from a 7-char bit string for settings/presets.
    // WrapWidth is appended as ":N" so presets round-trip it; the suffix is
    // optional, so 2.0.x settings files with a bare 7-char string still load.
    public string ToBits() {
        char[] b = new char[7];
        b[0] = WesternDigits ? '1' : '0';
        b[1] = RemoveZeroWidth ? '1' : '0';
        b[2] = RemoveDiacritics ? '1' : '0';
        b[3] = RemoveTatweel ? '1' : '0';
        b[4] = PunctToLatin ? '1' : '0';
        b[5] = NormalizeAlef ? '1' : '0';
        b[6] = NormalizeYaTa ? '1' : '0';
        string s = new string(b);
        if (WrapWidth > 0) s += ":" + WrapWidth.ToString();
        return s;
    }
    public static FixOptions FromBits(string s) {
        FixOptions o = new FixOptions();
        if (s == null || s.Length < 7) return o;
        o.WesternDigits = s[0] == '1';
        o.RemoveZeroWidth = s[1] == '1';
        o.RemoveDiacritics = s[2] == '1';
        o.RemoveTatweel = s[3] == '1';
        o.PunctToLatin = s[4] == '1';
        o.NormalizeAlef = s[5] == '1';
        o.NormalizeYaTa = s[6] == '1';
        int colon = s.IndexOf(':');
        if (colon >= 7 && colon + 1 < s.Length) {
            int w;
            if (int.TryParse(s.Substring(colon + 1), out w) && w >= 20 && w <= 200) o.WrapWidth = w;
        }
        return o;
    }
}

public class FixResult {
    public string Text = "";
    public string Summary = "";
    public int Total = 0;
}

// ------------------------------------------------------------------ //
//  Engine
// ------------------------------------------------------------------ //
public static class Engine {

    // letter -> [isolated, final, initial, medial]; '\0' = form not available
    static Dictionary<char, char[]> Forms = new Dictionary<char, char[]> {
        {'\u0621', new char[]{'\uFE80','\0','\0','\0'}},
        {'\u0622', new char[]{'\uFE81','\uFE82','\0','\0'}},
        {'\u0623', new char[]{'\uFE83','\uFE84','\0','\0'}},
        {'\u0624', new char[]{'\uFE85','\uFE86','\0','\0'}},
        {'\u0625', new char[]{'\uFE87','\uFE88','\0','\0'}},
        {'\u0626', new char[]{'\uFE89','\uFE8A','\uFE8B','\uFE8C'}},
        {'\u0627', new char[]{'\uFE8D','\uFE8E','\0','\0'}},
        {'\u0628', new char[]{'\uFE8F','\uFE90','\uFE91','\uFE92'}},
        {'\u0629', new char[]{'\uFE93','\uFE94','\0','\0'}},
        {'\u062A', new char[]{'\uFE95','\uFE96','\uFE97','\uFE98'}},
        {'\u062B', new char[]{'\uFE99','\uFE9A','\uFE9B','\uFE9C'}},
        {'\u062C', new char[]{'\uFE9D','\uFE9E','\uFE9F','\uFEA0'}},
        {'\u062D', new char[]{'\uFEA1','\uFEA2','\uFEA3','\uFEA4'}},
        {'\u062E', new char[]{'\uFEA5','\uFEA6','\uFEA7','\uFEA8'}},
        {'\u062F', new char[]{'\uFEA9','\uFEAA','\0','\0'}},
        {'\u0630', new char[]{'\uFEAB','\uFEAC','\0','\0'}},
        {'\u0631', new char[]{'\uFEAD','\uFEAE','\0','\0'}},
        {'\u0632', new char[]{'\uFEAF','\uFEB0','\0','\0'}},
        {'\u0633', new char[]{'\uFEB1','\uFEB2','\uFEB3','\uFEB4'}},
        {'\u0634', new char[]{'\uFEB5','\uFEB6','\uFEB7','\uFEB8'}},
        {'\u0635', new char[]{'\uFEB9','\uFEBA','\uFEBB','\uFEBC'}},
        {'\u0636', new char[]{'\uFEBD','\uFEBE','\uFEBF','\uFEC0'}},
        {'\u0637', new char[]{'\uFEC1','\uFEC2','\uFEC3','\uFEC4'}},
        {'\u0638', new char[]{'\uFEC5','\uFEC6','\uFEC7','\uFEC8'}},
        {'\u0639', new char[]{'\uFEC9','\uFECA','\uFECB','\uFECC'}},
        {'\u063A', new char[]{'\uFECD','\uFECE','\uFECF','\uFED0'}},
        {'\u0640', new char[]{'\u0640','\u0640','\u0640','\u0640'}},
        {'\u0641', new char[]{'\uFED1','\uFED2','\uFED3','\uFED4'}},
        {'\u0642', new char[]{'\uFED5','\uFED6','\uFED7','\uFED8'}},
        {'\u0643', new char[]{'\uFED9','\uFEDA','\uFEDB','\uFEDC'}},
        {'\u0644', new char[]{'\uFEDD','\uFEDE','\uFEDF','\uFEE0'}},
        {'\u0645', new char[]{'\uFEE1','\uFEE2','\uFEE3','\uFEE4'}},
        {'\u0646', new char[]{'\uFEE5','\uFEE6','\uFEE7','\uFEE8'}},
        {'\u0647', new char[]{'\uFEE9','\uFEEA','\uFEEB','\uFEEC'}},
        {'\u0648', new char[]{'\uFEED','\uFEEE','\0','\0'}},
        {'\u0649', new char[]{'\uFEEF','\uFEF0','\0','\0'}},
        {'\u064A', new char[]{'\uFEF1','\uFEF2','\uFEF3','\uFEF4'}},
        {'\u0679', new char[]{'\uFB66','\uFB67','\uFB68','\uFB69'}},
        {'\u067E', new char[]{'\uFB56','\uFB57','\uFB58','\uFB59'}},
        {'\u0686', new char[]{'\uFB7A','\uFB7B','\uFB7C','\uFB7D'}},
        {'\u0688', new char[]{'\uFB88','\uFB89','\0','\0'}},
        {'\u0691', new char[]{'\uFB8C','\uFB8D','\0','\0'}},
        {'\u0698', new char[]{'\uFB8A','\uFB8B','\0','\0'}},
        {'\u06A9', new char[]{'\uFB8E','\uFB8F','\uFB90','\uFB91'}},
        {'\u06AF', new char[]{'\uFB92','\uFB93','\uFB94','\uFB95'}},
        {'\u06BA', new char[]{'\uFB9E','\uFB9F','\0','\0'}},
        {'\u06BE', new char[]{'\uFBAA','\uFBAB','\uFBAC','\uFBAD'}},
        {'\u06C0', new char[]{'\uFBA4','\uFBA5','\0','\0'}},
        {'\u06C1', new char[]{'\uFBA6','\uFBA7','\uFBA8','\uFBA9'}},
        {'\u06CC', new char[]{'\uFBFC','\uFBFD','\uFBFE','\uFBFF'}},
        {'\u06D2', new char[]{'\uFBAE','\uFBAF','\0','\0'}},
        {'\u06D3', new char[]{'\uFBB0','\uFBB1','\0','\0'}}
    };

    static Dictionary<char, char[]> LamAlef = new Dictionary<char, char[]> {
        {'\u0622', new char[]{'\uFEF5','\uFEF6'}},
        {'\u0623', new char[]{'\uFEF7','\uFEF8'}},
        {'\u0625', new char[]{'\uFEF9','\uFEFA'}},
        {'\u0627', new char[]{'\uFEFB','\uFEFC'}}
    };

    public static Dictionary<char, string> Inverse = BuildInverse();

    static Dictionary<char, string> BuildInverse() {
        Dictionary<char, string> d = new Dictionary<char, string>();
        foreach (KeyValuePair<char, char[]> kv in Forms) {
            foreach (char f in kv.Value) {
                if (f != '\0' && !d.ContainsKey(f)) d[f] = kv.Key.ToString();
            }
        }
        foreach (KeyValuePair<char, char[]> kv in LamAlef) {
            foreach (char f in kv.Value) d[f] = "\u0644" + kv.Key.ToString();
        }
        return d;
    }

    public static bool IsTransparent(char c) {
        return (c >= '\u0610' && c <= '\u061A')
            || (c >= '\u064B' && c <= '\u065F')
            || c == '\u0670'
            || (c >= '\u06D6' && c <= '\u06DC')
            || (c >= '\u06DF' && c <= '\u06E4')
            || c == '\u06E7' || c == '\u06E8'
            || (c >= '\u06EA' && c <= '\u06ED')
            || (c >= '\u08D3' && c <= '\u08FF')
            || (c >= '\u0591' && c <= '\u05C7');
    }

    public static string Reshape(string text, out int count) {
        char[] chars = text.ToCharArray();
        StringBuilder sb = new StringBuilder();
        bool prevCapable = false;
        count = 0;
        int i = 0;
        while (i < chars.Length) {
            char ch = chars[i];
            if (IsTransparent(ch)) { sb.Append(ch); i++; continue; }
            char[] f;
            if (!Forms.TryGetValue(ch, out f)) { sb.Append(ch); prevCapable = false; i++; continue; }

            if (ch == '\u0644') {
                int j = i + 1;
                StringBuilder between = new StringBuilder();
                while (j < chars.Length && IsTransparent(chars[j])) { between.Append(chars[j]); j++; }
                char[] lig;
                if (j < chars.Length && LamAlef.TryGetValue(chars[j], out lig)) {
                    sb.Append(prevCapable ? lig[1] : lig[0]);
                    sb.Append(between.ToString());
                    count++;
                    prevCapable = false;
                    i = j + 1;
                    continue;
                }
            }

            int k = i + 1;
            while (k < chars.Length && IsTransparent(chars[k])) k++;
            bool nextJoinable = k < chars.Length && Forms.ContainsKey(chars[k]) && chars[k] != '\u0621';
            bool capable = f[2] != '\0';
            bool linkedBefore = prevCapable && f[1] != '\0' && ch != '\u0621';
            bool linkedAfter = capable && nextJoinable;
            char shaped = linkedBefore ? (linkedAfter ? f[3] : f[1]) : (linkedAfter ? f[2] : f[0]);
            if (shaped == '\0') shaped = f[0];
            if (shaped != ch) count++;
            sb.Append(shaped);
            prevCapable = capable;
            i++;
        }
        return sb.ToString();
    }

    static Regex RtlLine = new Regex("[\u0590-\u08FF\uFB1D-\uFDFD\uFE70-\uFEFC]");
    public static bool HasRtl(string s) { return s != null && RtlLine.IsMatch(s); }

    // whole-file markup must never travel through the plain-text path:
    // converting raw XML/SVG as text mangles it and pasting it into
    // Affinity puts literal markup on the canvas
    public static bool LooksLikeMarkup(string s) {
        if (s == null) return false;
        string t = s.TrimStart();
        if (t.StartsWith("<?xml") || t.StartsWith("<!DOCTYPE") || t.StartsWith("<svg")
            || t.StartsWith("<html") || t.StartsWith("<HTML")) return true;
        if (t.StartsWith("<") && s.Contains("</") && s.Contains(">")) return true;
        return false;
    }
    static Regex LtrRun = new Regex("[A-Za-z0-9\u00C0-\u024F](?:[A-Za-z0-9\u00C0-\u024F .,:/@&#%+\\-]*[A-Za-z0-9\u00C0-\u024F%])?");

    static Dictionary<char, char> Mirror = new Dictionary<char, char> {
        {'(', ')'}, {')', '('}, {'[', ']'}, {']', '['},
        {'{', '}'}, {'}', '{'}, {'\u00AB', '\u00BB'}, {'\u00BB', '\u00AB'},
        {'<', '>'}, {'>', '<'}
    };

    public static List<string> Graphemes(string s) {
        List<string> outp = new List<string>();
        foreach (char c in s) {
            if (outp.Count > 0 && IsTransparent(c)) outp[outp.Count - 1] += c;
            else outp.Add(c.ToString());
        }
        return outp;
    }

    static string VisualLine(string line) {
        if (!RtlLine.IsMatch(line)) return line;
        List<KeyValuePair<bool, string>> segs = new List<KeyValuePair<bool, string>>();
        int last = 0;
        foreach (Match m in LtrRun.Matches(line)) {
            if (m.Index > last) segs.Add(new KeyValuePair<bool, string>(false, line.Substring(last, m.Index - last)));
            segs.Add(new KeyValuePair<bool, string>(true, m.Value));
            last = m.Index + m.Length;
        }
        if (last < line.Length) segs.Add(new KeyValuePair<bool, string>(false, line.Substring(last)));
        segs.Reverse();
        StringBuilder sb = new StringBuilder();
        foreach (KeyValuePair<bool, string> seg in segs) {
            if (seg.Key) { sb.Append(seg.Value); continue; }
            List<string> gs = Graphemes(seg.Value);
            gs.Reverse();
            foreach (string g in gs) {
                if (g.Length == 1) {
                    char mc;
                    if (Mirror.TryGetValue(g[0], out mc)) { sb.Append(mc); continue; }
                }
                sb.Append(g);
            }
        }
        return sb.ToString();
    }

    public static string ToVisual(string text) {
        string[] lines = text.Replace("\r\n", "\n").Split('\n');
        for (int i = 0; i < lines.Length; i++) lines[i] = VisualLine(lines[i]);
        return string.Join("\r\n", lines);
    }

    static string StripSet(string s, string setDesc, ref int count) {
        // setDesc: pairs of range chars "lo hi lo hi ..."
        StringBuilder sb = new StringBuilder();
        foreach (char c in s) {
            bool drop = false;
            for (int i = 0; i + 1 < setDesc.Length; i += 2) {
                if (c >= setDesc[i] && c <= setDesc[i + 1]) { drop = true; break; }
            }
            if (drop) count++;
            else sb.Append(c);
        }
        return sb.ToString();
    }

    public static bool LooksConverted(string s) {
        bool pres = false, baseLetter = false;
        foreach (char c in s) {
            if ((c >= '\uFB50' && c <= '\uFDFD') || (c >= '\uFE70' && c <= '\uFEFC')) pres = true;
            else if (c != '\u0640' && Forms.ContainsKey(c)) baseLetter = true;
        }
        return pres && !baseLetter;
    }

    public static FixResult Convert(string text, FixOptions o) {
        string t = text;
        int nHidden = 0, nSpell = 0, nPunct = 0, nDigits = 0, nDia = 0, nTat = 0, nShape = 0;

        // ZWNJ/ZWJ are NOT stripped here: in Persian/Urdu they legitimately
        // break or force joining, so they must influence shaping first.
        if (o.RemoveZeroWidth) {
            t = StripSet(t, "\u200B\u200B\u200E\u200F\u202A\u202E\u2066\u2069\uFEFF\uFEFF", ref nHidden);
        } else {
            // direction marks always go - they corrupt visual order silently
            int dummy = 0;
            t = StripSet(t, "\u200E\u200F", ref dummy);
        }
        if (o.NormalizeAlef) {
            StringBuilder sb = new StringBuilder();
            foreach (char c in t) {
                if (c == '\u0622' || c == '\u0623' || c == '\u0625' || c == '\u0671') { sb.Append('\u0627'); nSpell++; }
                else sb.Append(c);
            }
            t = sb.ToString();
        }
        if (o.NormalizeYaTa) {
            StringBuilder sb = new StringBuilder();
            foreach (char c in t) {
                if (c == '\u0649') { sb.Append('\u064A'); nSpell++; }
                else if (c == '\u0629') { sb.Append('\u0647'); nSpell++; }
                else sb.Append(c);
            }
            t = sb.ToString();
        }
        if (o.PunctToLatin) {
            StringBuilder sb = new StringBuilder();
            foreach (char c in t) {
                if (c == '\u060C') { sb.Append(','); nPunct++; }
                else if (c == '\u061B') { sb.Append(';'); nPunct++; }
                else if (c == '\u061F') { sb.Append('?'); nPunct++; }
                else sb.Append(c);
            }
            t = sb.ToString();
        }
        if (o.WesternDigits) {
            StringBuilder sb = new StringBuilder();
            foreach (char c in t) {
                if (c >= '\u0660' && c <= '\u0669') { sb.Append((char)('0' + (c - '\u0660'))); nDigits++; }
                else if (c >= '\u06F0' && c <= '\u06F9') { sb.Append((char)('0' + (c - '\u06F0'))); nDigits++; }
                else if (c == '\u066A') { sb.Append('%'); nDigits++; }
                else sb.Append(c);
            }
            t = sb.ToString();
        }
        if (o.RemoveDiacritics) {
            t = StripSet(t, "\u064B\u065F\u0670\u0670\u05B0\u05BC\u05C1\u05C2\u05C7\u05C7", ref nDia);
        }
        if (o.RemoveTatweel) {
            t = StripSet(t, "\u0640\u0640", ref nTat);
        }
        int nWrap = 0;
        if (o.WrapWidth > 0) t = WrapLines(t, o.WrapWidth, ref nWrap);

        string shaped = Reshape(t, out nShape);
        // ZWNJ/ZWJ have done their joining work during shaping; drop them now
        if (o.RemoveZeroWidth) shaped = StripSet(shaped, "\u200C\u200D", ref nHidden);
        else { int dummy2 = 0; shaped = StripSet(shaped, "\u200C\u200D", ref dummy2); }
        FixResult r = new FixResult();
        r.Text = ToVisual(shaped);

        List<string> parts = new List<string>();
        if (nShape > 0) parts.Add(nShape.ToString() + " letters shaped");
        if (nDigits > 0) parts.Add(nDigits.ToString() + " digits");
        if (nHidden > 0) parts.Add(nHidden.ToString() + " hidden chars removed");
        if (nDia > 0) parts.Add(nDia.ToString() + " diacritics removed");
        if (nTat > 0) parts.Add(nTat.ToString() + " tatweel removed");
        if (nPunct > 0) parts.Add(nPunct.ToString() + " punctuation");
        if (nSpell > 0) parts.Add(nSpell.ToString() + " letters normalized");
        if (nWrap > 0) parts.Add(nWrap.ToString() + " line breaks added");
        r.Total = nShape + nDigits + nHidden + nDia + nTat + nPunct + nSpell + nWrap;
        r.Summary = parts.Count == 0 ? "no RTL letters found" : string.Join(", ", parts.ToArray());
        return r;
    }

    // hard-break long lines at word boundaries (logical order, pre-shaping)
    public static string WrapLines(string text, int width, ref int count) {
        string[] lines = text.Replace("\r\n", "\n").Split('\n');
        List<string> outp = new List<string>();
        foreach (string line in lines) {
            if (line.Length <= width) { outp.Add(line); continue; }
            int pos = 0;
            while (line.Length - pos > width) {
                int searchFrom = Math.Min(pos + width, line.Length - 1);
                int brk = line.LastIndexOf(' ', searchFrom);
                if (brk <= pos) brk = pos + width; // single word longer than width
                outp.Add(line.Substring(pos, brk - pos).TrimEnd());
                count++;
                pos = brk;
                while (pos < line.Length && line[pos] == ' ') pos++;
            }
            outp.Add(line.Substring(pos));
        }
        return string.Join("\n", outp.ToArray());
    }

    public static string Restore(string text) {
        string reversed = ToVisual(text);
        StringBuilder sb = new StringBuilder();
        foreach (char c in reversed) {
            string b;
            if (Inverse.TryGetValue(c, out b)) sb.Append(b);
            else sb.Append(c);
        }
        return sb.ToString();
    }

    // ---- character inspector helpers ----
    static Dictionary<int, string> NameMap = BuildNames();
    static Dictionary<int, string> BuildNames() {
        Dictionary<int, string> d = new Dictionary<int, string>();
        foreach (string row in UniNames.Table) {
            int bar = row.IndexOf('|');
            d[System.Convert.ToInt32(row.Substring(0, bar), 16)] = row.Substring(bar + 1);
        }
        return d;
    }

    public static string Inspect(string grapheme) {
        if (string.IsNullOrEmpty(grapheme)) return "";
        StringBuilder sb = new StringBuilder();
        bool first = true;
        foreach (char c in grapheme) {
            if (!first) sb.Append("  +  ");
            first = false;
            int cp = (int)c;
            sb.Append("U+");
            sb.Append(cp.ToString("X4"));
            string name;
            if (NameMap.TryGetValue(cp, out name)) { sb.Append(" "); sb.Append(name); }
            else { sb.Append(" "); sb.Append(ScriptOf(c)); }
            string baseLetter;
            if (Inverse.TryGetValue(c, out baseLetter) && baseLetter[0] != c) {
                sb.Append("  [from ");
                sb.Append(baseLetter);
                sb.Append("]");
            }
        }
        return sb.ToString();
    }

    static string ScriptOf(char c) {
        if (c >= '\u0600' && c <= '\u06FF') return "Arabic";
        if (c >= '\u0590' && c <= '\u05FF') return "Hebrew";
        if (c >= '\uFB50' && c <= '\uFDFD') return "Arabic Presentation Forms-A";
        if (c >= '\uFE70' && c <= '\uFEFC') return "Arabic Presentation Forms-B";
        if (c >= '0' && c <= '9') return "Digit";
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) return "Latin";
        if (c == ' ') return "Space";
        return "Other";
    }
}

// ------------------------------------------------------------------ //
//  Theme
// ------------------------------------------------------------------ //
// ------------------------------------------------------------------ //
//  Theme - lavender / card design language (light + dark)
//  Field names from 2.0.x are kept so PreviewPanel, PromptDialog and
//  AboutDialog keep compiling unchanged.
// ------------------------------------------------------------------ //
// Anchored on the logo's teal #1E9B8C (the v1.0/v2.0 brand colour).
//
// The accent is split into three roles because the brand teal on white is only
// 3.43:1 - fine for non-text marks (WCAG 1.4.11 needs 3:1) but short of the
// 4.5:1 AA needs for text sitting on it:
//   Accent     - the brand teal itself, for graphics: donut rings, toggle and
//                checkbox fills, focus rings, outlines
//   AccentFill - primary button background, deepened so a white label passes AA
//   AccentInk  - accent-coloured TEXT on card or tint (5.6:1+)
public class Theme {
    public Color Bg, Panel, Text, Sub, Border, Accent, AccentText, InputBg, PreviewBg, Good, Bad;
    public Color Card, Sidebar, AccentSoft, Shadow, Track;
    public Color AccentFill, AccentInk, AccentHover, AccentPress;
    public bool IsDark = false;

    public static Theme Light() {
        Theme t = new Theme();
        t.IsDark = false;
        t.Bg = Color.FromArgb(245, 248, 248);
        t.Card = Color.White;
        t.Sidebar = Color.White;
        t.Panel = Color.FromArgb(245, 248, 248);
        t.Text = Color.FromArgb(26, 46, 43);
        t.Sub = Color.FromArgb(94, 107, 112);
        t.Border = Color.FromArgb(220, 231, 229);
        t.Accent = Color.FromArgb(30, 155, 140);        // #1E9B8C brand
        t.AccentFill = Color.FromArgb(23, 120, 108);    // #17786C
        t.AccentHover = Color.FromArgb(19, 107, 98);    // #136B62
        t.AccentPress = Color.FromArgb(15, 90, 82);     // #0F5A52
        t.AccentInk = Color.FromArgb(19, 107, 98);      // #136B62
        t.AccentSoft = Color.FromArgb(227, 244, 242);   // #E3F4F2
        t.AccentText = Color.White;
        t.InputBg = Color.White;
        t.PreviewBg = Color.FromArgb(250, 252, 252);
        t.Good = Color.FromArgb(46, 125, 79);           // #2E7D4F
        t.Bad = Color.FromArgb(198, 40, 40);            // #C62828
        t.Shadow = Color.FromArgb(18, 0, 0, 0);
        t.Track = Color.FromArgb(230, 237, 236);
        return t;
    }

    public static Theme Dark() {
        Theme t = new Theme();
        t.IsDark = true;
        t.Bg = Color.FromArgb(18, 26, 25);              // #121A19
        t.Card = Color.FromArgb(28, 38, 36);            // #1C2624
        t.Sidebar = Color.FromArgb(28, 38, 36);
        t.Panel = Color.FromArgb(18, 26, 25);
        t.Text = Color.FromArgb(234, 242, 241);         // #EAF2F1
        t.Sub = Color.FromArgb(159, 178, 175);          // #9FB2AF
        t.Border = Color.FromArgb(42, 55, 53);          // #2A3735
        t.Accent = Color.FromArgb(43, 187, 169);        // #2BBBA9 brand, lifted for dark
        t.AccentFill = Color.FromArgb(43, 187, 169);
        t.AccentHover = Color.FromArgb(52, 205, 186);   // #34CDBA
        t.AccentPress = Color.FromArgb(33, 162, 146);   // #21A292
        t.AccentInk = Color.FromArgb(95, 217, 200);     // #5FD9C8
        t.AccentSoft = Color.FromArgb(23, 48, 44);      // #17302C
        t.AccentText = Color.FromArgb(6, 35, 31);       // dark ink on bright teal
        t.InputBg = Color.FromArgb(23, 31, 30);
        t.PreviewBg = Color.FromArgb(23, 31, 30);
        t.Good = Color.FromArgb(91, 214, 140);          // #5BD68C
        t.Bad = Color.FromArgb(255, 138, 133);          // #FF8A85
        t.Shadow = Color.FromArgb(90, 0, 0, 0);
        t.Track = Color.FromArgb(42, 55, 53);
        return t;
    }
}

// ------------------------------------------------------------------ //
//  Shared drawing helpers + font stack resolution
// ------------------------------------------------------------------ //
public static class Ui {
    static string family = null;

    // prefer a modern geometric sans when the user has one, else Segoe UI
    public static string Family() {
        if (family != null) return family;
        string[] want = new string[] { "Inter", "Poppins", "Segoe UI Variable Text", "Segoe UI" };
        List<string> have = new List<string>();
        try {
            foreach (FontFamily f in FontFamily.Families) have.Add(f.Name);
        } catch (Exception) { }
        foreach (string w in want) {
            if (have.Contains(w)) { family = w; return family; }
        }
        family = "Segoe UI";
        return family;
    }

    public static Font F(float size, FontStyle style) {
        try { return new Font(Family(), size, style); }
        catch (Exception) { return new Font("Segoe UI", size, style); }
    }
    public static Font F(float size) { return F(size, FontStyle.Regular); }

    public static GraphicsPath Round(Rectangle r, int radius) {
        GraphicsPath p = new GraphicsPath();
        if (radius <= 0) { p.AddRectangle(r); return p; }
        int d = radius * 2;
        if (d > r.Width) d = r.Width;
        if (d > r.Height) d = r.Height;
        p.AddArc(r.X, r.Y, d, d, 180, 90);
        p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
        p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
        p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
        p.CloseFigure();
        return p;
    }

    // cheap layered soft shadow - no blur available in plain GDI+
    public static void Shadow(Graphics g, Rectangle r, int radius, Color shade, int spread) {
        for (int i = spread; i >= 1; i--) {
            Rectangle rr = new Rectangle(r.X - i, r.Y - i + 1, r.Width + i * 2, r.Height + i * 2);
            int a = (int)(shade.A / (float)(i * 2.2f));
            if (a < 1) continue;
            using (GraphicsPath p = Round(rr, radius + i))
            using (Pen pen = new Pen(Color.FromArgb(a, shade.R, shade.G, shade.B), 1f)) {
                g.DrawPath(pen, p);
            }
        }
    }

    public static void Card(Graphics g, Rectangle r, Theme th, int radius, bool shadow) {
        g.SmoothingMode = SmoothingMode.AntiAlias;
        if (shadow) Shadow(g, r, radius, th.Shadow, 5);
        using (GraphicsPath p = Round(r, radius))
        using (Brush b = new SolidBrush(th.Card)) {
            g.FillPath(b, p);
            using (Pen pen = new Pen(th.Border, 1f)) g.DrawPath(pen, p);
        }
    }

    public static void FocusRing(Graphics g, Rectangle r, int radius, Color accent) {
        using (GraphicsPath p = Round(Rectangle.Inflate(r, 2, 2), radius + 2))
        using (Pen pen = new Pen(Color.FromArgb(140, accent), 2f)) {
            g.DrawPath(pen, p);
        }
    }

    public static Color Mix(Color a, Color b, float t) {
        return Color.FromArgb(
            (int)(a.R + (b.R - a.R) * t),
            (int)(a.G + (b.G - a.G) * t),
            (int)(a.B + (b.B - a.B) * t));
    }
}

// ------------------------------------------------------------------ //
//  Rounded white surface with a soft shadow. Children sit on top.
// ------------------------------------------------------------------ //
public class CardPanel : Panel {
    public Theme Th = Theme.Light();
    public int Radius = 14;
    public bool Shadowed = true;
    public string Title = "";

    public CardPanel() {
        DoubleBuffered = true;
        SetStyle(ControlStyles.ResizeRedraw, true);
    }

    protected override void OnPaintBackground(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.Clear(Th.Bg);
        Rectangle r = new Rectangle(6, 6, Width - 13, Height - 13);
        if (r.Width < 4 || r.Height < 4) return;
        Ui.Card(g, r, Th, Radius, Shadowed);
        if (Title != null && Title.Length > 0) {
            using (Font f = Ui.F(11.5F, FontStyle.Bold))
            using (Brush b = new SolidBrush(Th.Text)) {
                g.DrawString(Title, f, b, r.X + 18, r.Y + 15);
            }
        }
    }
}

// ------------------------------------------------------------------ //
//  Pill button - Primary (filled), Secondary (outlined), Ghost (text).
//  Keyboard accessible: tab stop, Enter/Space activate, visible focus.
// ------------------------------------------------------------------ //
public class PillButton : Control {
    public const int Primary = 0, Secondary = 1, Ghost = 2;
    public int Kind = Primary;
    public Theme Th = Theme.Light();
    public string Glyph = "";
    bool hot = false, down = false;

    public PillButton() {
        DoubleBuffered = true;
        SetStyle(ControlStyles.Selectable | ControlStyles.ResizeRedraw, true);
        TabStop = true;
        Height = 38;
        Cursor = Cursors.Hand;
    }

    protected override void OnMouseEnter(EventArgs e) { hot = true; Invalidate(); base.OnMouseEnter(e); }
    protected override void OnMouseLeave(EventArgs e) { hot = false; down = false; Invalidate(); base.OnMouseLeave(e); }
    protected override void OnMouseDown(MouseEventArgs e) { down = true; Focus(); Invalidate(); base.OnMouseDown(e); }
    protected override void OnMouseUp(MouseEventArgs e) { down = false; Invalidate(); base.OnMouseUp(e); }
    protected override void OnGotFocus(EventArgs e) { Invalidate(); base.OnGotFocus(e); }
    protected override void OnLostFocus(EventArgs e) { Invalidate(); base.OnLostFocus(e); }

    protected override bool IsInputKey(Keys k) {
        if (k == Keys.Space || k == Keys.Enter) return true;
        return base.IsInputKey(k);
    }
    protected override void OnKeyDown(KeyEventArgs e) {
        if (e.KeyCode == Keys.Space || e.KeyCode == Keys.Enter) {
            down = true; Invalidate();
            e.Handled = true;
        }
        base.OnKeyDown(e);
    }
    protected override void OnKeyUp(KeyEventArgs e) {
        if (e.KeyCode == Keys.Space || e.KeyCode == Keys.Enter) {
            down = false; Invalidate();
            OnClick(EventArgs.Empty);
            e.Handled = true;
        }
        base.OnKeyUp(e);
    }

    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        // a CardPanel paints the page bg outside its rounded rect, so reading
        // Parent.BackColor here left grey bands across the card surface
        g.Clear(Parent is CardPanel ? Th.Card : (Parent != null ? Parent.BackColor : Th.Card));
        Rectangle r = new Rectangle(0, 0, Width - 1, Height - 1);
        int rad = Height / 2;

        Color fill, fore, edge = Color.Empty;
        if (Kind == Primary) {
            // explicit hover/press tones per theme: lightening a teal fill would
            // drop the white label below AA, so both states go deeper in light
            fill = Th.AccentFill;
            if (hot) fill = Th.AccentHover;
            if (down) fill = Th.AccentPress;
            fore = Th.AccentText;
        } else if (Kind == Secondary) {
            fill = hot ? Th.AccentSoft : Th.Card;
            if (down) fill = Ui.Mix(Th.AccentSoft, Th.Accent, 0.18f);
            fore = Th.AccentInk;
            edge = Th.Accent;
        } else {
            fill = hot ? Th.AccentSoft : Color.Transparent;
            fore = Th.Sub;
            if (hot) fore = Th.AccentInk;
        }

        if (fill != Color.Transparent) {
            using (GraphicsPath p = Ui.Round(r, rad))
            using (Brush b = new SolidBrush(fill)) g.FillPath(b, p);
        }
        if (edge != Color.Empty) {
            using (GraphicsPath p = Ui.Round(r, rad))
            using (Pen pen = new Pen(edge, 1.4f)) g.DrawPath(pen, p);
        }
        if (Focused) Ui.FocusRing(g, new Rectangle(1, 1, Width - 3, Height - 3), rad, Th.Accent);

        string label = Text;
        if (Glyph != null && Glyph.Length > 0) label = Glyph + "  " + Text;
        using (Font f = Ui.F(9.75F, Kind == Primary ? FontStyle.Bold : FontStyle.Regular))
        using (Brush b = new SolidBrush(Enabled ? fore : Th.Sub)) {
            StringFormat sf = new StringFormat();
            sf.Alignment = StringAlignment.Center;
            sf.LineAlignment = StringAlignment.Center;
            sf.Trimming = StringTrimming.EllipsisCharacter;
            sf.FormatFlags |= StringFormatFlags.NoWrap;
            g.DrawString(label, f, b, new RectangleF(6, 0, Width - 12, Height), sf);
            sf.Dispose();
        }
    }
}

// ------------------------------------------------------------------ //
//  Sidebar navigation row: glyph + label, purple pill when active.
// ------------------------------------------------------------------ //
public class NavItem : Control {
    public Theme Th = Theme.Light();
    public string Glyph = "";
    public bool Active = false;
    bool hot = false;

    public NavItem() {
        DoubleBuffered = true;
        SetStyle(ControlStyles.Selectable | ControlStyles.ResizeRedraw, true);
        TabStop = true;
        Height = 42;
        Cursor = Cursors.Hand;
    }

    protected override void OnMouseEnter(EventArgs e) { hot = true; Invalidate(); base.OnMouseEnter(e); }
    protected override void OnMouseLeave(EventArgs e) { hot = false; Invalidate(); base.OnMouseLeave(e); }
    protected override void OnMouseDown(MouseEventArgs e) { Focus(); base.OnMouseDown(e); }
    protected override void OnGotFocus(EventArgs e) { Invalidate(); base.OnGotFocus(e); }
    protected override void OnLostFocus(EventArgs e) { Invalidate(); base.OnLostFocus(e); }

    protected override bool IsInputKey(Keys k) {
        if (k == Keys.Space || k == Keys.Enter) return true;
        return base.IsInputKey(k);
    }
    protected override void OnKeyUp(KeyEventArgs e) {
        if (e.KeyCode == Keys.Space || e.KeyCode == Keys.Enter) { OnClick(EventArgs.Empty); e.Handled = true; }
        base.OnKeyUp(e);
    }

    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.Clear(Th.Sidebar);
        Rectangle r = new Rectangle(0, 2, Width - 1, Height - 5);
        if (Active) {
            using (GraphicsPath p = Ui.Round(r, 10))
            using (Brush b = new SolidBrush(Th.AccentSoft)) g.FillPath(b, p);
            using (Brush b = new SolidBrush(Th.Accent))
                g.FillRectangle(b, new Rectangle(0, r.Y + 8, 3, r.Height - 16));
        } else if (hot) {
            using (GraphicsPath p = Ui.Round(r, 10))
            using (Brush b = new SolidBrush(Ui.Mix(Th.Sidebar, Th.AccentSoft, 0.55f))) g.FillPath(b, p);
        }
        if (Focused) Ui.FocusRing(g, new Rectangle(2, 4, Width - 6, Height - 9), 10, Th.Accent);

        Color fore = Active ? Th.AccentInk : Th.Sub;
        StringFormat sf = new StringFormat();
        sf.LineAlignment = StringAlignment.Center;
        sf.FormatFlags |= StringFormatFlags.NoWrap;
        sf.Trimming = StringTrimming.EllipsisCharacter;
        using (Font gf = Ui.F(11F))
        using (Brush b = new SolidBrush(fore))
            g.DrawString(Glyph, gf, b, new RectangleF(14, 0, 26, Height), sf);
        using (Font tf = Ui.F(9.75F, Active ? FontStyle.Bold : FontStyle.Regular))
        using (Brush b = new SolidBrush(Active ? Th.Text : Th.Sub))
            g.DrawString(Text, tf, b, new RectangleF(42, 0, Width - 48, Height), sf);
        sf.Dispose();
    }
}

// ------------------------------------------------------------------ //
//  Donut statistic ring (reference design's stat cards)
// ------------------------------------------------------------------ //
public class DonutStat : Control {
    public Theme Th = Theme.Light();
    public string Caption = "";
    public string Unit = "";
    public string Value = "0";
    public float Fraction = 0f;   // 0..1 sweep

    public DonutStat() {
        DoubleBuffered = true;
        SetStyle(ControlStyles.ResizeRedraw, true);
        Height = 62;
    }

    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.Clear(Th.Card);

        int d = 44;
        int cx = Width - d - 6;
        int cy = (Height - d) / 2;
        Rectangle ring = new Rectangle(cx, cy, d, d);

        using (Pen bg = new Pen(Th.Track, 4f)) g.DrawEllipse(bg, ring);
        float sweep = Fraction < 0f ? 0f : (Fraction > 1f ? 1f : Fraction);
        if (sweep > 0f) {
            using (Pen p = new Pen(Th.Accent, 4f)) {
                p.StartCap = LineCap.Round; p.EndCap = LineCap.Round;
                g.DrawArc(p, ring, -90f, 360f * sweep);
            }
        }
        StringFormat mid = new StringFormat();
        mid.Alignment = StringAlignment.Center;
        mid.LineAlignment = StringAlignment.Center;
        using (Font vf = Ui.F(9.5F, FontStyle.Bold))
        using (Brush b = new SolidBrush(Th.AccentInk))   // text, not a mark
            g.DrawString(Value, vf, b, new RectangleF(cx, cy, d, d), mid);

        StringFormat left = new StringFormat();
        left.FormatFlags |= StringFormatFlags.NoWrap;
        left.Trimming = StringTrimming.EllipsisCharacter;
        using (Font cf = Ui.F(9F))
        using (Brush b = new SolidBrush(Th.Text))
            g.DrawString(Caption, cf, b, new RectangleF(4, Height / 2 - 16, Width - d - 16, 18), left);
        using (Font uf = Ui.F(8F))
        using (Brush b = new SolidBrush(Th.Sub))
            g.DrawString(Unit, uf, b, new RectangleF(4, Height / 2 + 2, Width - d - 16, 16), left);
        mid.Dispose(); left.Dispose();
    }
}

// ------------------------------------------------------------------ //
//  iOS-style toggle. Exposes Checked / CheckedChanged like a CheckBox.
// ------------------------------------------------------------------ //
public class ToggleSwitch : Control {
    public Theme Th = Theme.Light();
    bool val = false;
    public event EventHandler CheckedChanged;

    public bool Checked {
        get { return val; }
        set { if (val != value) { val = value; Invalidate(); if (CheckedChanged != null) CheckedChanged(this, EventArgs.Empty); } }
    }

    public ToggleSwitch() {
        DoubleBuffered = true;
        SetStyle(ControlStyles.Selectable | ControlStyles.ResizeRedraw, true);
        TabStop = true;
        Size = new Size(46, 26);
        Cursor = Cursors.Hand;
    }

    protected override void OnMouseDown(MouseEventArgs e) { Focus(); Checked = !Checked; base.OnMouseDown(e); }
    protected override void OnGotFocus(EventArgs e) { Invalidate(); base.OnGotFocus(e); }
    protected override void OnLostFocus(EventArgs e) { Invalidate(); base.OnLostFocus(e); }
    protected override bool IsInputKey(Keys k) {
        if (k == Keys.Space || k == Keys.Enter) return true;
        return base.IsInputKey(k);
    }
    protected override void OnKeyUp(KeyEventArgs e) {
        if (e.KeyCode == Keys.Space || e.KeyCode == Keys.Enter) { Checked = !Checked; e.Handled = true; }
        base.OnKeyUp(e);
    }

    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        // a CardPanel paints the page bg outside its rounded rect, so reading
        // Parent.BackColor here left grey bands across the card surface
        g.Clear(Parent is CardPanel ? Th.Card : (Parent != null ? Parent.BackColor : Th.Card));
        Rectangle r = new Rectangle(0, 2, Width - 1, Height - 5);
        using (GraphicsPath p = Ui.Round(r, r.Height / 2))
        using (Brush b = new SolidBrush(val ? Th.Accent : Th.Track)) g.FillPath(b, p);
        if (Focused) Ui.FocusRing(g, r, r.Height / 2, Th.Accent);
        int kd = r.Height - 6;
        int kx = val ? r.Right - kd - 3 : r.X + 3;
        // ON: AccentText, which is dark on the lifted dark-mode teal. OFF: the
        // card colour with an outline, since a white knob on the light-theme
        // track was all but invisible.
        using (Brush b = new SolidBrush(val ? Th.AccentText : Th.Card))
            g.FillEllipse(b, kx, r.Y + 3, kd, kd);
        if (!val) {
            using (Pen pen = new Pen(Th.Border, 1f)) g.DrawEllipse(pen, kx, r.Y + 3, kd, kd);
        }
    }
}

// ------------------------------------------------------------------ //
//  Flat checkbox with the accent tick. Drop-in for CheckBox usage
//  (Checked / CheckedChanged / Text), so option wiring is unchanged.
// ------------------------------------------------------------------ //
public class FlatCheck : Control {
    public Theme Th = Theme.Light();
    bool val = false;
    bool hot = false;
    public event EventHandler CheckedChanged;

    public bool Checked {
        get { return val; }
        set { if (val != value) { val = value; Invalidate(); if (CheckedChanged != null) CheckedChanged(this, EventArgs.Empty); } }
    }

    public FlatCheck() {
        DoubleBuffered = true;
        SetStyle(ControlStyles.Selectable | ControlStyles.ResizeRedraw, true);
        TabStop = true;
        Height = 24;
        Cursor = Cursors.Hand;
    }

    protected override void OnMouseEnter(EventArgs e) { hot = true; Invalidate(); base.OnMouseEnter(e); }
    protected override void OnMouseLeave(EventArgs e) { hot = false; Invalidate(); base.OnMouseLeave(e); }
    protected override void OnMouseDown(MouseEventArgs e) { Focus(); Checked = !Checked; base.OnMouseDown(e); }
    protected override void OnGotFocus(EventArgs e) { Invalidate(); base.OnGotFocus(e); }
    protected override void OnLostFocus(EventArgs e) { Invalidate(); base.OnLostFocus(e); }
    protected override bool IsInputKey(Keys k) {
        if (k == Keys.Space || k == Keys.Enter) return true;
        return base.IsInputKey(k);
    }
    protected override void OnKeyUp(KeyEventArgs e) {
        if (e.KeyCode == Keys.Space || e.KeyCode == Keys.Enter) { Checked = !Checked; e.Handled = true; }
        base.OnKeyUp(e);
    }

    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        // a CardPanel paints the page bg outside its rounded rect, so reading
        // Parent.BackColor here left grey bands across the card surface
        g.Clear(Parent is CardPanel ? Th.Card : (Parent != null ? Parent.BackColor : Th.Card));
        Rectangle box = new Rectangle(1, (Height - 17) / 2, 17, 17);
        using (GraphicsPath p = Ui.Round(box, 5)) {
            using (Brush b = new SolidBrush(val ? Th.Accent : Th.InputBg)) g.FillPath(b, p);
            using (Pen pen = new Pen(val ? Th.Accent : (hot ? Th.Accent : Th.Border), 1.4f)) g.DrawPath(pen, p);
        }
        if (val) {
            // AccentText, not white: on the lifted dark-mode teal a white tick
            // sits at 2.4:1, while the dark ink reads at 6.9:1
            using (Pen pen = new Pen(Th.AccentText, 2f)) {
                pen.StartCap = LineCap.Round; pen.EndCap = LineCap.Round;
                g.DrawLines(pen, new Point[] {
                    new Point(box.X + 4, box.Y + 9),
                    new Point(box.X + 7, box.Y + 12),
                    new Point(box.X + 13, box.Y + 5) });
            }
        }
        if (Focused) Ui.FocusRing(g, box, 5, Th.Accent);
        StringFormat sf = new StringFormat();
        sf.LineAlignment = StringAlignment.Center;
        sf.Trimming = StringTrimming.EllipsisCharacter;
        sf.FormatFlags |= StringFormatFlags.NoWrap;
        using (Font f = Ui.F(9.25F))
        using (Brush b = new SolidBrush(Th.Text))
            g.DrawString(Text, f, b, new RectangleF(26, 0, Width - 28, Height), sf);
        sf.Dispose();
    }
}

// ------------------------------------------------------------------ //
//  Affinity-accurate preview: draws each glyph LTR with no bidi engine,
//  exactly like Affinity. Click any glyph to inspect it.
// ------------------------------------------------------------------ //
public class PreviewPanel : Panel {
    string text = "";
    List<Rectangle> boxes = new List<Rectangle>();
    List<string> glyphs = new List<string>();
    public Theme Th = Theme.Light();
    public delegate void GlyphHandler(string g);
    public event GlyphHandler GlyphPicked;
    Font arial = new Font("Arial", 15F);

    public PreviewPanel() {
        DoubleBuffered = true;
        AutoScroll = true;
        SetStyle(ControlStyles.ResizeRedraw, true);
    }

    public void SetText(string t) {
        text = t == null ? "" : t;
        Invalidate();
    }

    protected override void OnPaint(PaintEventArgs e) {
        base.OnPaint(e);
        Graphics g = e.Graphics;
        g.Clear(Th.PreviewBg);
        g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;
        boxes.Clear(); glyphs.Clear();
        StringFormat sf = (StringFormat)StringFormat.GenericTypographic.Clone();
        sf.FormatFlags |= StringFormatFlags.MeasureTrailingSpaces;
        float lineH = arial.GetHeight(g) + 6f;
        float y = 8f + AutoScrollPosition.Y;
        float maxW = 0f;
        string[] lines = text.Replace("\r\n", "\n").Split('\n');
        using (Brush br = new SolidBrush(Th.Text)) {
            foreach (string line in lines) {
                float x = 10f + AutoScrollPosition.X;
                foreach (string gr in Engine.Graphemes(line)) {
                    SizeF sz = g.MeasureString(gr, arial, 1000, sf);
                    float w = sz.Width;
                    if (w < 2f) w = arial.Size * 0.45f;
                    g.DrawString(gr, arial, br, x, y, sf);
                    boxes.Add(new Rectangle((int)(x - AutoScrollPosition.X), (int)(y - AutoScrollPosition.Y), (int)w + 1, (int)lineH));
                    glyphs.Add(gr);
                    x += w;
                }
                if (x > maxW) maxW = x;
                y += lineH;
            }
        }
        AutoScrollMinSize = new Size((int)maxW + 20, (int)(y - AutoScrollPosition.Y) + 10);
    }

    protected override void OnMouseClick(MouseEventArgs e) {
        base.OnMouseClick(e);
        Point p = new Point(e.X - AutoScrollPosition.X, e.Y - AutoScrollPosition.Y);
        for (int i = 0; i < boxes.Count; i++) {
            if (boxes[i].Contains(p)) {
                if (GlyphPicked != null) GlyphPicked(glyphs[i]);
                return;
            }
        }
    }
}

